using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private readonly ShoppingCart _sut = new();

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _sut.AddItem("SKU-001", 2, 9.99m);

        Assert.AreEqual(19.98m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_SumsCorrectly()
    {
        _sut.AddItem("SKU-001", 1, 10.00m);
        _sut.AddItem("SKU-002", 3, 5.00m);

        Assert.AreEqual(25.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _sut.AddItem("SKU-001", 1, 10.00m);
        _sut.AddItem("SKU-001", 2, 10.00m);

        Assert.AreEqual(30.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentException(int quantity)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.AddItem("SKU-001", quantity, 10.00m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero price")]
    [DataRow(-5.00, DisplayName = "Negative price")]
    public void AddItem_InvalidPrice_ThrowsArgumentException(double price)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.AddItem("SKU-001", 1, (decimal)price));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void AddItem_InvalidSku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.AddItem(sku!, 1, 10.00m));
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-001", 2, 10.00m);
        _sut.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _sut.RemoveItem("DOES-NOT-EXIST"));
    }

    [TestMethod]
    public void RemoveItem_OneOfMany_OnlyRemovesSpecifiedItem()
    {
        _sut.AddItem("SKU-001", 1, 10.00m);
        _sut.AddItem("SKU-002", 1, 20.00m);

        _sut.RemoveItem("SKU-001");

        Assert.AreEqual(20.00m, _sut.CalculateTotal());
    }

    // --- CalculateTotal Tests ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemove_ReflectsCurrentState()
    {
        _sut.AddItem("SKU-001", 2, 15.00m);
        _sut.AddItem("SKU-002", 1, 7.50m);
        _sut.RemoveItem("SKU-001");

        Assert.AreEqual(7.50m, _sut.CalculateTotal());
    }

    // --- ApplyCoupon Tests ---

    [TestMethod]
    [DataRow("SAVE10", 10.00, DisplayName = "10% off coupon")]
    [DataRow("SAVE20", 20.00, DisplayName = "20% off coupon")]
    public void ApplyCoupon_ValidPercentageCoupon_ReducesTotal(string code, double discountPercent)
    {
        _sut.AddItem("SKU-001", 1, 100.00m);
        _sut.ApplyCoupon(code);

        var expected = 100.00m - (100.00m * (decimal)discountPercent / 100m);
        Assert.AreEqual(expected, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        _sut.AddItem("SKU-001", 1, 50.00m);

        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon("INVALID_CODE"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null code")]
    [DataRow("", DisplayName = "Empty code")]
    public void ApplyCoupon_NullOrEmpty_ThrowsArgumentException(string? code)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_ThrowsInvalidOperationException()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _sut.ApplyCoupon("SAVE10"));
    }
}

